import type { InspectorStoreState } from "./InspectorStore";
import { ConversationEventType, UtteranceType, type Stack } from "../types";
import { isBotUtteranceEmpty, isUtterance } from "../utils/conversation";

const ALLOWED_PATTERNS = ["pattern_session_start", "pattern_completed", "pattern_user_silence"];

function isUserVisibleFrame(frame: Stack) {
  return !frame.flowId?.startsWith("pattern_") || ALLOWED_PATTERNS.includes(frame.flowId);
}

export const selectLatestStack = (state: InspectorStoreState) => {
  const { stack } = state;
  for (let i = stack.length - 1; i >= 0; i--) {
    if (isUserVisibleFrame(stack[i])) return stack[i];
  }
  return undefined;
};

export const selectStackToShow = (state: InspectorStoreState) => {
  const { selectedElement } = state;
  if (selectedElement?.metadata?.flow_id && selectedElement?.metadata?.step_id) {
    return {
      frameId: selectedElement.id,
      flowId: selectedElement.metadata.flow_id,
      stepId: selectedElement.metadata.step_id,
      ended: false,
    };
  }
  return selectLatestStack(state);
};

export const selectConversationForSelectedElement = (state: InspectorStoreState) => {
  const { selectedElement, conversationList } = state;
  if (!selectedElement?.id) return undefined;
  return conversationList.find((conversation) =>
    conversation.events.some((event) => event?.id === selectedElement.id),
  );
};

/**
 * Whether the connected project runs the skill-based engine (Mantle).
 *
 * Reserved for engine-level dispatch that no event type can express: which
 * middle pane to mount, which memory pane to show, whether the conversation
 * log groups tool writes, and the "Active skill"/"Active flow" label. Per-event
 * rendering forks by `conversationEventType` instead — Mantle emits dedicated
 * skill, ordered-block, memory, and tool events, so a row or detail panel picks
 * its engine variant from the event, not from this flag.
 */
export const selectIsMantleEngine = (state: InspectorStoreState) => state.engineType === "mantle";

/**
 * The active skill's catalog entry joined with its runtime position, or
 * undefined while routing (no active flow frame) or in flow-based (v1) mode.
 *
 * The engine stamps the owning skill id on the active-skill ref, so this is a
 * direct catalog lookup — no flow-id scan. Falls back to the last active skill
 * so the pane keeps showing the previous skill between skills, rather than
 * dropping to an empty state.
 *
 * `flowId` here is NOT a v1 flow: skills have no flow, only ordered blocks. It
 * is the compiled ordered-block id currently running inside the skill
 * (`ActiveSkillRef.ordered_block_id`), the block whose steps the engine is
 * executing. Consumers compare it against `block.ordered_block_id` to find and
 * highlight the active block; it is never a user-authored flow name. The
 * property keeps the `flowId` name because the sibling
 * `selectSkillForSelectedElement` derives the same slot from a selected
 * event's flow scope (a tracker-level flow id), and both feed one shape.
 */
export const selectActiveSkill = (state: InspectorStoreState) => {
  const activeRef = state.skillState?.active_skill ?? state.lastActiveSkillRef;
  if (!activeRef?.skill_id || !state.skillCatalog) return undefined;
  const skill = state.skillCatalog[activeRef.skill_id];
  if (!skill) return undefined;
  return { skill, flowId: activeRef.ordered_block_id, stepId: activeRef.step_id };
};

/**
 * The skill id carried by the selected element, if any: an event's own
 * `skillId`, else a memory write's provenance `skill_id`, else the element's
 * metadata `skill_id`. The engine stamps one of these on every skill-scoped
 * event and memory write, so no flow-id scan is needed.
 */
const skillIdForSelectedElement = (
  selectedElement: InspectorStoreState["selectedElement"],
): string | undefined => {
  if (selectedElement?.__typename !== "ConversationEvent") return undefined;
  return (
    selectedElement.skillId ??
    selectedElement.metadata?.mantle_write_provenance?.skill_id ??
    selectedElement.metadata?.skill_id ??
    undefined
  );
};

/**
 * The flow/step position an element carries, if any. Memory and block events
 * put the flow on the top-level `flowId`; some raw events only carry it in
 * metadata; skill lifecycle events carry none at all (the engine's
 * SkillActivated has just a skill id) — for those the scope is the skill
 * document without a step highlight.
 */
const flowScopeOf = (element: NonNullable<InspectorStoreState["selectedElement"]>) => {
  const flowId =
    (element.__typename === "ConversationEvent" ? element.flowId : undefined) ||
    element.metadata?.flow_id ||
    null;
  const stepId =
    (element.__typename === "ConversationEvent" ? element.stepId : undefined) ||
    element.metadata?.step_id ||
    null;
  return { flowId, stepId };
};

/**
 * Locates the selected element among a conversation's events. Most elements
 * match by id; the synthesized LLM-call rows exist only in ChatSection's merged
 * display list (mergeLlmCallsIntoConversations), never in conversationList, so
 * an id lookup silently misses them — those match by their record timestamp
 * (llmCallToConversationEvent stamps it as originalTimestamp) instead.
 */
const anchorIndexInConversation = (
  conversation: InspectorStoreState["conversationList"][number],
  element: NonNullable<InspectorStoreState["selectedElement"]>,
): number => {
  const byId = conversation.events.findIndex((event) => event.id === element.id);
  if (byId !== -1) return byId;
  const timestamp = element.originalTimestamp;
  if (timestamp === undefined) return -1;
  let insertAt = conversation.events.findIndex(
    (event) => (event.originalTimestamp ?? 0) > timestamp,
  );
  if (insertAt === -1) insertAt = conversation.events.length;
  // An LLM call precedes its consequences, so it anchors to the event just
  // before the first later one — the same slot mergeLlmCallsIntoConversations
  // inserts it at.
  return insertAt - 1;
};

/**
 * The skill scope the selected element pins the pane to: the element's own
 * stamped scope when it has one, else the nearest preceding skill-stamped
 * event in the same conversation. Chat messages and synthesized LLM-call rows
 * carry no skill scope of their own, but "the skill at this message" is the one
 * whose events last ran before it — a positional lookup over ids the engine
 * stamped, not an inference. Returns null when no skill-stamped event precedes
 * the selection (it predates any skill activity).
 */
type Conversation = InspectorStoreState["conversationList"][number];

/**
 * Locates the one conversation that holds the selected element, together with
 * the element's anchor index in it. An element lives in exactly one
 * conversation, so this returns the first (only) match, or null.
 */
const locateElementInConversations = (
  state: InspectorStoreState,
  element: NonNullable<InspectorStoreState["selectedElement"]>,
): { conversation: Conversation; anchorIndex: number } | null => {
  for (const conversation of state.conversationList) {
    const anchorIndex = anchorIndexInConversation(conversation, element);
    if (anchorIndex !== -1) return { conversation, anchorIndex };
  }
  return null;
};

const skillScopeForElement = (
  state: InspectorStoreState,
  element: NonNullable<InspectorStoreState["selectedElement"]>,
) => {
  const ownSkillId = skillIdForSelectedElement(element);
  if (ownSkillId) {
    return { skillId: ownSkillId, ...flowScopeOf(element) };
  }
  const located = locateElementInConversations(state, element);
  if (!located) return null;
  const { conversation, anchorIndex } = located;
  // The nearest skill-stamped event scanning backward is the most recently
  // active skill; it is set once and then pins which skill's flow/step we read.
  let mostRecentSkillId: string | undefined;
  let flowId: string | null = null;
  let stepId: string | null = null;
  for (let position = anchorIndex; position >= 0; position--) {
    const candidate = conversation.events[position];
    const candidateSkillId = skillIdForSelectedElement(candidate);
    if (!candidateSkillId) continue;
    if (!mostRecentSkillId) mostRecentSkillId = candidateSkillId;
    if (candidateSkillId !== mostRecentSkillId) continue;
    const scope = flowScopeOf(candidate);
    // Accumulate flowId (e.g. from OrderedBlockEntered) and stepId separately:
    // block-entry events carry flowId but no stepId; step events carry both.
    if (flowId === null && scope.flowId) flowId = scope.flowId;
    if (stepId === null && scope.stepId) stepId = scope.stepId;
    if (flowId !== null && stepId !== null) break;
  }
  if (!mostRecentSkillId) return null;
  return { skillId: mostRecentSkillId, flowId, stepId };
};

/**
 * The skill to display in the skill pane. While any element is selected the
 * pane is in travel mode: the skill active at that moment — the element's own
 * stamped scope, or the nearest preceding skill-stamped event for elements
 * without one (chat messages, LLM-call rows) — with the step active then.
 *
 * When nothing skill-stamped precedes the selection (it predates any skill
 * activity) this returns undefined so the pane shows its empty state — truthful:
 * no skill was active then. It never falls back to the live skill while a
 * selection stands; only a cleared selection shows the live active skill.
 */
export const selectSkillForSelectedElement = (state: InspectorStoreState) => {
  const { selectedElement, skillCatalog } = state;
  if (!skillCatalog) return selectActiveSkill(state);
  if (!selectedElement) return selectActiveSkill(state);
  const scope = skillScopeForElement(state, selectedElement);
  const skill = scope ? skillCatalog[scope.skillId] : undefined;
  if (!scope || !skill) return undefined;
  return { skill, flowId: scope.flowId, stepId: scope.stepId };
};

/**
 * The events to replay and the anchor index for reconstructing skill state at
 * the selected element, or undefined when nothing is selected or no
 * skill-stamped event precedes it. The anchor is the selection itself (or, for
 * an unmatched LLM-call row, the event it slots after); replay runs up to and
 * including it. SkillSection combines this with the anchored skill's catalog
 * entry via deriveSkillStateAt.
 */
export const selectReconstructionForSelectedElement = (state: InspectorStoreState) => {
  const { selectedElement } = state;
  if (!selectedElement) return undefined;
  const scope = skillScopeForElement(state, selectedElement);
  if (!scope) return undefined;
  const located = locateElementInConversations(state, selectedElement);
  if (!located) return undefined;
  const { conversation, anchorIndex } = located;
  // When clicking a SkillActivated entry in History, show the skill in its
  // final visible state for that invocation rather than the empty just-activated
  // state. Scan forward to the last event still stamped with this skill before
  // the invocation ends (next SkillActivated or a different skill's events).
  let effectiveAnchor = anchorIndex;
  const selectedEvent = conversation.events[anchorIndex];
  if (
    selectedEvent?.__typename === "ConversationEvent" &&
    selectedEvent.conversationEventType === ConversationEventType.SkillActivated &&
    selectedEvent.skillId === scope.skillId
  ) {
    for (let i = anchorIndex + 1; i < conversation.events.length; i++) {
      const ev = conversation.events[i];
      if (ev.__typename !== "ConversationEvent") continue;
      if (ev.conversationEventType === ConversationEventType.SkillActivated) break;
      const evSkillId = skillIdForSelectedElement(ev);
      if (evSkillId === scope.skillId) {
        effectiveAnchor = i;
      } else if (evSkillId !== undefined) {
        break;
      }
    }
  }
  return {
    events: conversation.events,
    anchorIndex: effectiveAnchor,
    anchoredSkillId: scope.skillId,
  };
};

/** Runtime status of one ordered block, defaulting to inactive when unknown. */
export const selectBlockStatus = (state: InspectorStoreState, blockFlowId: string) =>
  state.skillState?.blocks[blockFlowId]?.status ?? "inactive";

/** Evaluation result for a condition expression; undefined when not evaluated. */
export const selectConditionResult = (state: InspectorStoreState, condition: string) =>
  state.skillState?.evaluated_conditions[condition];

/** The skill-engine memory map (contract view + system entries), or undefined. */
export const selectSkillMemory = (state: InspectorStoreState) => state.skillState?.memory;

export const selectWaitingForResponse = (state: InspectorStoreState) => {
  if (state.waitingForUserInput || state.inputDisabled) return false;

  const events = state.conversationList.at(-1)?.events ?? [];
  for (let i = events.length - 1; i >= 0; i--) {
    const event = events[i];
    if (!isUtterance(event)) continue;
    if (event.type === UtteranceType.User) return true;
    return isBotUtteranceEmpty(event);
  }

  return true;
};
